final class ObrainDatabase extends ffi.Opaque {}

final class ObrainEdge extends ffi.Opaque {}

final class ObrainNode extends ffi.Opaque {}

final class ObrainResult extends ffi.Opaque {}

enum ObrainStatus {
  OBRAIN_STATUS_OK(0),
  OBRAIN_STATUS_ERROR_DATABASE(1),
  OBRAIN_STATUS_ERROR_QUERY(2),
  OBRAIN_STATUS_ERROR_TRANSACTION(3),
  OBRAIN_STATUS_ERROR_STORAGE(4),
  OBRAIN_STATUS_ERROR_IO(5),
  OBRAIN_STATUS_ERROR_SERIALIZATION(6),
  OBRAIN_STATUS_ERROR_INTERNAL(7),
  OBRAIN_STATUS_ERROR_NULL_POINTER(8),
  OBRAIN_STATUS_ERROR_INVALID_UTF8(9);

  final int value;
  const ObrainStatus(this.value);

  static ObrainStatus fromValue(int value) => switch (value) {
        0 => OBRAIN_STATUS_OK,
        1 => OBRAIN_STATUS_ERROR_DATABASE,
        2 => OBRAIN_STATUS_ERROR_QUERY,
        3 => OBRAIN_STATUS_ERROR_TRANSACTION,
        4 => OBRAIN_STATUS_ERROR_STORAGE,
        5 => OBRAIN_STATUS_ERROR_IO,
        6 => OBRAIN_STATUS_ERROR_SERIALIZATION,
        7 => OBRAIN_STATUS_ERROR_INTERNAL,
        8 => OBRAIN_STATUS_ERROR_NULL_POINTER,
        9 => OBRAIN_STATUS_ERROR_INVALID_UTF8,
        _ => throw ArgumentError('Unknown value for ObrainStatus: $value'),
      };
}

final class ObrainTransaction extends ffi.Opaque {}
